import 'package:flutter/material.dart';
class AppTheme { static ThemeData light()=>_base(Brightness.light); static ThemeData dark()=>_base(Brightness.dark); static ThemeData _base(Brightness b){final scheme=ColorScheme.fromSeed(seedColor:const Color(0xFF3157D5),brightness:b);return ThemeData(useMaterial3:true,colorScheme:scheme,fontFamily:'Arial',scaffoldBackgroundColor:b==Brightness.light?const Color(0xFFF7F8FC):const Color(0xFF10131A),cardTheme:const CardThemeData(margin:EdgeInsets.symmetric(vertical:5),elevation:0),inputDecorationTheme:const InputDecorationTheme(border:OutlineInputBorder(),filled:true),navigationBarTheme:const NavigationBarThemeData(height:70));}}
